CAMERA = {
    "name": "cam",
    "camera_type": "opencv",
    "source": 0,
    "pipeline": {"name": "hsv_detection", "settings": {}},
}

PLUGINS = {
    "frame_processors": {"passthrough": {}},
    "trackers": {"FRC/object_tracker": {}},
    "utilities": {"target_selector": {}},
}


def _camera(name="cam", **extra):
    entry = copy.deepcopy(CAMERA)
    entry["name"] = name
    entry.update(extra)
    return entry


def _write_config(tmp: str, data: dict) -> str:
    path = Path(tmp) / "config.json"
    path.write_text(json.dumps(data))
    return str(path)


def _config_file(
    tmp: str,
    *,
    admin=True,
    cameras=None,
    plugins=None,
    allow_remote_restart=None,
    **top_level,
) -> str:
    data = {
        "admin": admin,
        "camera_configs": cameras if cameras is not None else {"cam": _camera()},
        "plugins": copy.deepcopy(plugins if plugins is not None else PLUGINS),
    }
    if allow_remote_restart is not None:
        data["allow_remote_restart"] = allow_remote_restart
    data.update(top_level)
    return _write_config(tmp, data)


def _client(path: str):
    config = iSpyConfig(file_path=path, create=False)
    return config, create_app(cameras=[], config=config).flask_app.test_client()


def _graph(client) -> dict:
    response = client.get("/api/editor/graph")
    assert response.status_code == 200, response.get_json()
    return response.get_json()["graph"]


def _apply_defaults(nodes):
    for node in nodes:
        settings = node.setdefault("settings", {})
        for key, value in (node.get("defaults") or {}).items():
            settings.setdefault(key, copy.deepcopy(value))


def _ready_graph(client, *, edges=True) -> dict:
    graph = _graph(client)
    _apply_defaults(graph["nodes"])
    if not edges:
        graph["edges"] = []
    return graph


def _post_validate(client, graph, *, nodes=None, edges=None):
    return client.post(
        "/api/editor/validate",
        json={
            "nodes": graph["nodes"] if nodes is None else nodes,
            "edges": graph.get("edges", []) if edges is None else edges,
        },
    )


def _post_save(client, graph, *, nodes=None, edges=None, layout=None):
    payload = {
        "nodes": graph["nodes"] if nodes is None else nodes,
        "edges": graph.get("edges", []) if edges is None else edges,
    }
    if layout is not None:
        payload["layout"] = layout
    return client.post("/api/editor/graph", json=payload)


def _codes(response) -> set:
    return {error["code"] for error in response.get_json().get("errors", [])}


def _error(response, code):
    return next(
        error
        for error in response.get_json().get("errors", [])
        if error["code"] == code
    )


def _lane_nodes(nodes, camera):
    return [node for node in nodes if node.get("camera") == camera]


def _rename_lane(nodes, old, new):
    renamed = copy.deepcopy(nodes)
    for node in renamed:
        if node.get("type") == "utility":
            node["sources"] = [
                new if source == old else source for source in node.get("sources", [])
            ]
            continue
        if node.get("camera") != old:
            continue
        node["camera"] = new
        node["id"] = node["id"].replace(f":{old}", f":{new}")
        if node.get("type") == "camera":
            node["camera"] = new
            node["label"] = new
            node["id"] = f"camera:{new}"
            node["renamed_from"] = old
    return renamed


