    def test_graph_has_five_locked_columns_and_utility_branch(self):
        with tempfile.TemporaryDirectory() as tmp:
            _config, client = _client(_config_file(tmp))
            graph = _graph(client)

            self.assertEqual(
                [column["label"] for column in graph["columns"]],
                [
                    "Camera",
                    "Frame Processor",
                    "Pipeline",
                    "Tracker",
                    "Utility",
                ],
            )
            self.assertEqual(
                [column["type"] for column in graph["columns"]],
                ["camera", "frame_processor", "pipeline", "tracker", "utility"],
            )
            self.assertEqual([column["count"] for column in graph["columns"]], [1] * 5)
            self.assertEqual(
                graph["lane_order"], ["cam"]
            )
            self.assertEqual(graph["utility_order"], ["target_selector"])
            self.assertEqual(graph["lanes"][0]["camera"], "cam")
            self.assertEqual(graph["lanes"][0]["index"], 0)
            self.assertEqual(graph["utility_sources"], {"target_selector": ["cam"]})
            self.assertNotIn("layout", graph)
            self.assertIn("viewport", graph)

            nodes = {node["id"]: node for node in graph["nodes"]}
            camera = nodes["camera:cam"]
            processor = nodes["frame_processor:cam:passthrough"]
            pipeline = nodes["pipeline:cam"]
            tracker = nodes["tracker:cam:FRC/object_tracker"]
            utility = nodes["utility:target_selector"]
            for node in (camera, processor, pipeline, tracker):
                self.assertEqual(node["lane"], 0)
            self.assertIsNone(utility["lane"])
            self.assertEqual(
                [camera["column_index"], processor["column_index"], pipeline["column_index"], tracker["column_index"], utility["column_index"]],
                [0, 1, 2, 3, 4],
            )
            xs = [camera["x"], processor["x"], pipeline["x"], tracker["x"], utility["x"]]
            self.assertEqual(xs, [COLUMN_X[name] for name in ("camera", "frame_processor", "pipeline", "tracker", "utility")])
            self.assertEqual(utility["sources"], ["cam"])

            kinds = [edge["kind"] for edge in graph["edges"]]
            self.assertEqual(
                kinds,
                [
                    "camera_frame_processor",
                    "frame_processor_pipeline",
                    "pipeline_tracker",
                    "tracker_utility",
                ],
            )
            by_id = nodes
            for edge in graph["edges"]:
                self.assertLess(
                    by_id[edge["from"]]["column_index"],
                    by_id[edge["to"]]["column_index"],
                )
            self.assertEqual(utility["shared_count"], 1)

    def test_settings_and_defaults_are_separate_until_confirmed(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = _config_file(tmp)
            _config, client = _client(path)
            graph = _graph(client)
            tracker = next(
                node for node in graph["nodes"] if node["type"] == "tracker"
            )
            self.assertNotIn("distance_threshold", tracker["settings"])
            self.assertEqual(tracker["defaults"]["distance_threshold"], 0.5)
            self.assertIn("distance_threshold", tracker["completion"]["required"])
            self.assertIn("distance_threshold", tracker["completion"]["missing"])
            self.assertFalse(tracker["completion"]["complete"])
            self.assertTrue(
                all(edge["state"] == "incomplete" for edge in graph["edges"])
            )

            response = _post_validate(client, graph)
            self.assertEqual(response.status_code, 400)
            self.assertIn("settings_incomplete", _codes(response))

            _apply_defaults(graph["nodes"])
            response = _post_validate(client, graph)
            self.assertEqual(response.status_code, 200, response.get_json())
            self.assertTrue(response.get_json()["ok"])
            self.assertTrue(
                response.get_json()["completion"][
                    "tracker:cam:FRC/object_tracker"
                ]["complete"]
            )

            # Completion state only affects the derived edge decoration.  The
            # saved edge list itself is unchanged.
            response = _post_save(client, graph)
            self.assertEqual(response.status_code, 200, response.get_json())
            saved = json.loads(Path(path).read_text())
            self.assertEqual(
                saved["plugins"]["trackers"]["FRC/object_tracker"]["distance_threshold"],
                0.5,
            )
            self.assertEqual(
                saved["plugins"]["trackers"]["FRC/object_tracker"]["stale_threshold"],
                1.0,
            )

            reloaded = _graph(client)
            tracker = next(
                node for node in reloaded["nodes"] if node["type"] == "tracker"
            )
            self.assertEqual(tracker["settings"]["distance_threshold"], 0.5)
            self.assertTrue(tracker["completion"]["complete"])
            self.assertTrue(all(edge["state"] == "complete" for edge in reloaded["edges"]))

