    def test_missing_lane_columns_have_actionable_messages(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = _config_file(tmp)
            _config, client = _client(path)
            graph = _ready_graph(client)
            original = Path(path).read_text()

            cases = [
                (
                    "frame_processor",
                    "lane_missing_frame_processor",
                    "Lane 'cam' is missing a frame processor. Add one to fill the Frame Processor column.",
                ),
                (
                    "pipeline",
                    "lane_missing_pipeline",
                    "Lane 'cam' is missing a pipeline. Add one to fill the Pipeline column.",
                ),
                (
                    "tracker",
                    "lane_missing_tracker",
                    "Lane 'cam' is missing a tracker. Add one to fill the Tracker column.",
                ),
            ]
            for node_type, code, message in cases:
                with self.subTest(node_type=node_type):
                    nodes = [
                        node for node in copy.deepcopy(graph["nodes"]) if node["type"] != node_type
                    ]
                    # Edges would reference the removed node; lane structure is
                    # validated independently of the optional edge list.
                    response = client.post(
                        "/api/editor/validate", json={"nodes": nodes}
                    )
                    self.assertEqual(response.status_code, 400)
                    self.assertIn(code, _codes(response))
                    self.assertEqual(_error(response, code)["message"], message)
                    self.assertTrue(_error(response, code)["node"].startswith("camera:"))

                    save = client.post("/api/editor/graph", json={"nodes": nodes})
                    self.assertEqual(save.status_code, 400)
                    self.assertEqual(Path(path).read_text(), original)

            response = client.post("/api/editor/validate", json={"nodes": []})
            self.assertEqual(response.status_code, 400)
            self.assertIn("no_cameras", _codes(response))
            self.assertEqual(
                _error(response, "no_cameras")["message"],
                "Add at least one camera lane before saving.",
            )

    def test_duplicate_nodes_are_rejected_per_lane(self):
        with tempfile.TemporaryDirectory() as tmp:
            _config, client = _client(_config_file(tmp))
            graph = _ready_graph(client)

            duplicate_pipeline = copy.deepcopy(
                next(node for node in graph["nodes"] if node["type"] == "pipeline")
            )
            duplicate_pipeline["id"] = "pipeline:cam:duplicate"
            response = client.post(
                "/api/editor/validate",
                json={"nodes": graph["nodes"] + [duplicate_pipeline]},
            )
            self.assertEqual(response.status_code, 400)
            self.assertIn("duplicate_column", _codes(response))
            self.assertEqual(
                _error(response, "duplicate_column")["message"],
                "Lane 'cam' has more than one Pipeline node. Keep exactly one node per column.",
            )
            self.assertEqual(
                _error(response, "duplicate_column")["node"],
                "pipeline:cam:duplicate",
            )

            duplicate_tracker = copy.deepcopy(
                next(node for node in graph["nodes"] if node["type"] == "tracker")
            )
            duplicate_tracker["id"] = "tracker:cam:other"
            duplicate_tracker["plugin"] = "example/example_tracker"
            response = client.post(
                "/api/editor/validate",
                json={"nodes": graph["nodes"] + [duplicate_tracker]},
            )
            self.assertEqual(response.status_code, 400)
            duplicate_errors = [
                error
                for error in response.get_json()["errors"]
                if error["code"] == "duplicate_column"
            ]
            self.assertTrue(duplicate_errors)
            self.assertEqual(
                duplicate_errors[0]["message"],
                "Lane 'cam' has more than one Tracker node. Keep exactly one node per column.",
            )

            duplicate_utility = copy.deepcopy(
                next(node for node in graph["nodes"] if node["type"] == "utility")
            )
            duplicate_utility["id"] = "utility:target_selector:copy"
            response = client.post(
                "/api/editor/validate",
                json={"nodes": graph["nodes"] + [duplicate_utility]},
            )
            self.assertEqual(response.status_code, 400)
            self.assertIn("duplicate_utility", _codes(response))
            self.assertEqual(
                _error(response, "duplicate_utility")["message"],
                "Utility 'target_selector' can only be placed once.",
            )

            duplicate_camera = copy.deepcopy(
                next(node for node in graph["nodes"] if node["type"] == "camera")
            )
            response = client.post(
                "/api/editor/validate",
                json={"nodes": graph["nodes"] + [duplicate_camera]},
            )
            self.assertEqual(response.status_code, 400)
            self.assertIn("duplicate_camera", _codes(response))

