    def test_tracker_utility_edges_select_sources_and_structural_edges_are_required(self):
        with tempfile.TemporaryDirectory() as tmp:
            _config, client = _client(_config_file(tmp))
            graph = _ready_graph(client)
            utility = next(
                node for node in graph["nodes"] if node["type"] == "utility"
            )
            utility["sources"] = []
            no_edges = [edge for edge in graph["edges"] if edge["kind"] != "tracker_utility"]
            response = _post_validate(client, graph, edges=no_edges)
            self.assertEqual(response.status_code, 400)
            self.assertIn("utility_no_inputs", _codes(response))

            missing_chain = [
                edge for edge in graph["edges"] if edge["kind"] != "camera_frame_processor"
            ]
            response = _post_validate(client, graph, edges=missing_chain)
            self.assertEqual(response.status_code, 400)
            self.assertIn("lane_missing_connection", _codes(response))
            self.assertEqual(
                _error(response, "lane_missing_connection")["message"],
                "Lane 'cam' is missing the Camera -> Frame Processor connection.",
            )

            reversed_edge = {
                "from": "pipeline:cam",
                "to": "camera:cam",
            }
            response = _post_validate(
                client, graph, edges=graph["edges"] + [reversed_edge]
            )
            self.assertEqual(response.status_code, 400)
            self.assertIn("edge_wrong_direction", _codes(response))

    def test_edge_validation_covers_direction_skip_lane_support_and_ports(self):
        nodes = {
            "camera:left": {
                "id": "camera:left",
                "type": "camera",
                "column": "camera",
                "lane": 0,
            },
            "camera:right": {
                "id": "camera:right",
                "type": "camera",
                "column": "camera",
                "lane": 1,
            },
            "fp:left": {
                "id": "fp:left",
                "type": "frame_processor",
                "column": "frame_processor",
                "lane": 0,
                "plugin": "limited",
                "supported_pipelines": ["allowed"],
            },
            "fp:right": {
                "id": "fp:right",
                "type": "frame_processor",
                "column": "frame_processor",
                "lane": 1,
                "plugin": "right",
            },
            "pipeline:left": {
                "id": "pipeline:left",
                "type": "pipeline",
                "column": "pipeline",
                "lane": 0,
                "plugin": "other",
            },
            "tracker:left": {
                "id": "tracker:left",
                "type": "tracker",
                "column": "tracker",
                "lane": 0,
                "plugin": "tracker",
            },
            "utility": {
                "id": "utility",
                "type": "utility",
                "column": "utility",
                "lane": None,
                "plugin": "utility",
            },
            "widget": {
                "id": "widget",
                "type": "widget",
                "column": "widget",
                "lane": 0,
            },
        }

        def run(edges):
            return _validate_edges(edges, nodes)

        self.assertEqual(
            [error["code"] for error in run([{"from": "pipeline:left", "to": "camera:left"}])],
            ["edge_wrong_direction"],
        )
        self.assertEqual(
            [error["code"] for error in run([{"from": "camera:left", "to": "pipeline:left"}])],
            ["edge_skipped_column"],
        )
        self.assertEqual(
            [error["code"] for error in run([{"from": "camera:left", "to": "fp:right"}])],
            ["edge_cross_lane"],
        )
        self.assertEqual(
            [error["code"] for error in run([{"from": "tracker:left", "to": "utility"}])],
            [],
        )
        self.assertEqual(
            [error["code"] for error in run([{"from": "utility", "to": "tracker:left"}])],
            ["edge_wrong_direction"],
        )
        errors = run([{"from": "fp:left", "to": "pipeline:left"}])
        self.assertEqual([error["code"] for error in errors], ["edge_pipeline_unsupported"])
        self.assertEqual(
            errors[0]["message"],
            "Frame processor 'limited' does not support pipeline 'other'.",
        )
        self.assertEqual(
            [error["code"] for error in run([{"from": "missing", "to": "utility"}])],
            ["edge_endpoint_missing"],
        )
        self.assertEqual(
            [error["code"] for error in run([{"from": "widget", "to": "utility"}])],
            ["edge_type"],
        )
        self.assertEqual(
            [error["code"] for error in run([{"from": "camera:left", "to": "nope"}])],
            ["edge_endpoint_missing"],
        )

