    def test_new_physical_camera_requires_detection_but_urls_and_existing_do_not(self):
        with tempfile.TemporaryDirectory() as tmp:
            _config, client = _client(_config_file(tmp))
            graph = _ready_graph(client)
            camera = next(node for node in graph["nodes"] if node["type"] == "camera")
            new_camera = copy.deepcopy(camera)
            new_camera.update(
                {
                    "id": "camera:new",
                    "camera": "new",
                    "label": "new",
                    "lane": 1,
                    "settings": copy.deepcopy(camera["settings"]),
                }
            )
            _apply_defaults([new_camera])
            new_camera["settings"]["source"] = 991

            with patch("iSpy.web.modules.editor._detected_devices", return_value=[]):
                response = client.post(
                    "/api/editor/validate",
                    json={"nodes": graph["nodes"] + [new_camera]},
                )
                self.assertEqual(response.status_code, 400)
                self.assertIn("camera_undetected", _codes(response))

                new_camera["settings"]["source"] = "rtsp://example/stream"
                response = client.post(
                    "/api/editor/validate",
                    json={"nodes": graph["nodes"] + [new_camera]},
                )
                self.assertNotIn("camera_undetected", _codes(response))

                new_camera["settings"]["source"] = "samples/frame.png"
                response = client.post(
                    "/api/editor/validate",
                    json={"nodes": graph["nodes"] + [new_camera]},
                )
                self.assertNotIn("camera_undetected", _codes(response))

                response = client.post(
                    "/api/editor/validate",
                    json={"nodes": graph["nodes"] + [new_camera]},
                )
                self.assertNotIn("camera_undetected", _codes(response))

            # Existing physical cameras keep working even when discovery is
            # temporarily empty.
            with patch("iSpy.web.modules.editor._detected_devices", return_value=[]):
                base_camera = next(
                    node for node in graph["nodes"] if node["type"] == "camera"
                )
                response = client.post(
                    "/api/editor/validate", json={"nodes": graph["nodes"]}
                )
                self.assertNotIn("camera_undetected", _codes(response))
                self.assertEqual(base_camera["settings"]["source"], 0)

            with patch(
                "iSpy.web.modules.editor._detected_devices",
                return_value=[{"path": 992, "name": "Detected"}],
            ):
                new_camera["settings"]["source"] = 992
                response = client.post(
                    "/api/editor/validate",
                    json={"nodes": graph["nodes"] + [new_camera]},
                )
                self.assertNotIn("camera_undetected", _codes(response))

