    def test_device_discovery_cache_claim_filter_and_refresh(self):
        old_cache = editor_module._DEVICE_CACHE
        old_ts = editor_module._DEVICE_CACHE_TS
        try:
            editor_module._DEVICE_CACHE = []
            editor_module._DEVICE_CACHE_TS = 0.0
            with tempfile.TemporaryDirectory() as tmp:
                path = _config_file(tmp)
                config, _client_obj = _client(path)
                with patch.object(
                    OpenCVCamera,
                    "discover",
                    return_value=[
                        {"path": 0, "name": "Claimed"},
                        {"path": 1, "name": "Free"},
                    ],
                ) as discover:
                    devices = _detected_devices(config)
                    self.assertEqual([device["path"] for device in devices], [1])
                    self.assertEqual(
                        discover.call_args.kwargs["claimed_sources"], {"0"}
                    )
                    discover.assert_called_once()

                    _detected_devices(config)
                    discover.assert_called_once()

                    _detected_devices(config, refresh=True)
                    self.assertEqual(discover.call_count, 2)
        finally:
            editor_module._DEVICE_CACHE = old_cache
            editor_module._DEVICE_CACHE_TS = old_ts

