    def test_public_ip_save_denied_and_admin_token_allowed(self):
        with tempfile.TemporaryDirectory() as tmp:
            _config, client = _client(_config_file(tmp))
            old = os.environ.get("ISPY_ADMIN_TOKEN")
            os.environ["ISPY_ADMIN_TOKEN"] = "secret"
            try:
                denied = client.post(
                    "/api/editor/graph",
                    json={"nodes": []},
                    environ_base={"REMOTE_ADDR": "203.0.113.9"},
                )
                allowed = client.post(
                    "/api/editor/graph",
                    json={"nodes": []},
                    headers={"X-iSpy-Admin-Token": "secret"},
                    environ_base={"REMOTE_ADDR": "203.0.113.9"},
                )
            finally:
                if old is None:
                    os.environ.pop("ISPY_ADMIN_TOKEN", None)
                else:
                    os.environ["ISPY_ADMIN_TOKEN"] = old
            self.assertEqual(denied.status_code, 403)
            self.assertIn("robot LAN", denied.get_json()["error"])
            self.assertNotEqual(allowed.status_code, 403)

